package com.example.crikstats.data.remote

import com.example.crikstats.data.model.PlayerStats
import kotlinx.coroutines.delay
import javax.inject.Inject
import javax.inject.Singleton

@Singleton
class CricketApiServiceImpl @Inject constructor() : CricketApiService {

    override suspend fun getPlayerStats(): PlayerStats {
        delay(1500)
        return PlayerStats(
            name = "Virat Kohli",
            matches = 253,
            average = 57.8
        )
    }
}

package com.example.crikstats.data.remote

import com.example.crikstats.data.model.PlayerStats
import okhttp3.Interceptor
import okhttp3.MediaType.Companion.toMediaType
import okhttp3.Protocol
import okhttp3.Response
import okhttp3.ResponseBody.Companion.toResponseBody
import com.google.gson.Gson

class MockInterceptor : Interceptor {

    private val gson = Gson()

    override fun intercept(chain: Interceptor.Chain): Response {
        val request = chain.request()
        val path = request.url.encodedPath

        Thread.sleep(1500)

        val responseBody = when {
            path.contains("virat-kohli") -> {
                val mockData = PlayerStats(
                    name = "Virat Kohli",
                    matches = 253,
                    average = 57.8
                )
                gson.toJson(mockData)
            }
            else -> """{"error": "Endpoint not found"}"""
        }

        return Response.Builder()
            .code(200)
            .message("OK")
            .request(request)
            .protocol(Protocol.HTTP_1_1)
            .body(responseBody.toResponseBody("application/json".toMediaType()))
            .build()
    }
}

